action.code:
pw = {p['account_name']: p['password'] for p in apis.supervisor.show_account_passwords()}
token = apis.venmo.login(username='paul_mill@gmail.com', password=pw['venmo'])['access_token']
total=0; n=0
for i in range(20):
    r = apis.venmo.show_transactions(access_token=token, direction='received', min_created_at='2023-01-01', max_created_at='2023-12-31', page_index=i, page_limit=20)
    if not r: break
    for t in r:
        total += t['like_count']; n+=1
print(total, n)

